.conversation-history-btn {
   display: inline-flex;
  align-items: center;
  padding: 6px 20px;
  border-radius: 9px;
	border-color: #2563eb;
	margin-right: 5px;
  font-size: 14px;
  font-weight: 600;
  background-color: #fff;
  color: #2563eb;
